<?php
$adminPage='transactions';$adminTitle='Money movement';$adminPermission='transactions.view';require __DIR__.'/../includes/admin_header.php';$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();requirePermission('transactions.reverse');$reason=trim($_POST['reason']??'');if(strlen($reason)<8)throw new InvalidArgumentException('Provide a specific reversal reason.');$result=(new FinancialService($pdo))->reverse(trim($_POST['reference']??''),(int)$_SESSION['user_id'],$reason);$notice='Correcting transaction '.$result['reference'].' was posted.';}catch(Throwable $e){$error=$e->getMessage();}}$type=$_GET['type']??'';$status=$_GET['status']??'';$q=trim($_GET['q']??'');$params=[];$where=['1=1'];if($type!==''){$where[]='ft.type=?';$params[]=$type;}if($status!==''){$where[]='ft.status=?';$params[]=$status;}if($q!==''){$where[]='(ft.reference LIKE ? OR u.email LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}$stmt=$pdo->prepare('SELECT ft.*,u.full_name,u.email,a.account_number FROM financial_transactions ft JOIN users u ON u.user_id=ft.user_id JOIN accounts a ON a.account_id=ft.account_id WHERE '.implode(' AND ',$where).' ORDER BY ft.created_at DESC LIMIT 200');$stmt->execute($params);$rows=$stmt->fetchAll();
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><form class="toolbar" method="get"><div class="field"><label>Reference or email</label><input name="q" value="<?=e($q)?>"></div><div class="field"><label>Type</label><select name="type"><option value="">All types</option><?php foreach(['card_funding','card_transfer','credit_disbursement','credit_repayment','reversal'] as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=e(str_replace('_',' ',$v))?></option><?php endforeach?></select></div><div class="field"><label>Status</label><select name="status"><option value="">All statuses</option><?php foreach(['pending','processing','completed','failed','reversed'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach?></select></div><button class="button button-primary">Filter</button></form><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference/time</th><th>Customer</th><th>Type</th><th>Amount/fee</th><th>Provider</th><th>Status</th><th>Correction</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="mono"><?=e($row['reference'])?><br><small><?=e(formatDate($row['created_at']))?></small></td><td><?=e($row['full_name'])?><br><small><?=e($row['account_number'])?></small></td><td><?=e(str_replace('_',' ',$row['type']))?></td><td class="money"><?=Money::format((int)$row['amount_cents'])?><br><small>Fee <?=Money::format((int)$row['fee_cents'])?></small></td><td class="mono"><?=e($row['provider_reference']??'—')?></td><td><span class="badge <?=e($row['status'])?>"><?=e($row['status'])?></span></td><td><?php if(can('transactions.reverse')&&$row['status']==='completed'&&$row['type']!=='reversal'):?><form method="post" class="compact-form"><?=csrfField()?><input type="hidden" name="reference" value="<?=e($row['reference'])?>"><input name="reason" maxlength="220" required placeholder="Correction reason"><button class="button button-danger">Reverse</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach?></tbody></table></div><?php if(!$rows):?><div class="empty">No transactions match these filters.</div><?php endif?></section><?php require __DIR__.'/../includes/admin_footer.php';?>
